#include <stdio.h>
int factorial(int n) {
printf("enter=%d\n",n);
if(n==0) return 0;
int result=n*factorial(n-1);
printf("leave=%d result=%d\n",n,result);
return result;
}
int main(void) {
int n=3;
if(n<0 || n>5) { puts("rejected"); return 0; }
int result=factorial(n);
printf("result=%d\n",result);
return 0;
}

